package cn.xingbao.domain;
import jakarta.persistence.Entity;
@Entity public class LearningContent extends BaseEntity {private String category;private String icon="📖";private String title;private String readingTime="3 分钟";private String intro;private String steps;private String tip;private Integer sortOrder=100;private boolean published=true;public String getCategory(){return category;}public void setCategory(String v){category=v;}public String getIcon(){return icon;}public void setIcon(String v){icon=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getReadingTime(){return readingTime;}public void setReadingTime(String v){readingTime=v;}public String getIntro(){return intro;}public void setIntro(String v){intro=v;}public String getSteps(){return steps;}public void setSteps(String v){steps=v;}public String getTip(){return tip;}public void setTip(String v){tip=v;}public Integer getSortOrder(){return sortOrder;}public void setSortOrder(Integer v){sortOrder=v;}public boolean isPublished(){return published;}public void setPublished(boolean v){published=v;}}
